import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/sheets/charts-insert.png",m=JSON.parse('{"title":"Add a chart","description":"Turn a range of cells into a bar, line, area, pie, or scatter chart, and place images on a sheet.","frontmatter":{"title":"Add a chart","description":"Turn a range of cells into a bar, line, area, pie, or scatter chart, and place images on a sheet.","type":"how-to"},"headers":[],"relativePath":"sheets/charts.md","filePath":"sheets/charts.md"}'),s={name:"sheets/charts.md"};function i(l,e,h,c,d,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="add-a-chart" tabindex="-1">Add a chart <a class="header-anchor" href="#add-a-chart" aria-label="Permalink to &quot;Add a chart&quot;">​</a></h1><p>Turn a range of cells into a bar, line, area, pie, or scatter chart, and place images on a sheet.</p><p>A chart reads its cells every time it draws, so it updates as soon as you change the data.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access. Viewers see charts and images but can&#39;t add or change them.</li><li>Select at least 2 rows and 2 columns. Include the header row so the chart can name its series.</li><li>Images: PNG, JPEG, GIF, or WebP, up to 10 MB. Larger images are shrunk to fit.</li></ul></div><h2 id="insert-a-chart" tabindex="-1">Insert a chart <a class="header-anchor" href="#insert-a-chart" aria-label="Permalink to &quot;Insert a chart&quot;">​</a></h2><ol><li>Open the sheet and select the data, including the header row. For example, select <strong>A1:C7</strong>.</li><li>Click <strong>Insert chart</strong> (the bar chart icon) in the toolbar.</li></ol><p>A bar chart appears beside the data: to the right, or below it when there is no room. Its title comes from your headers, for example <code>Revenue and Cost by Month</code>, or <code>Chart</code> when the range has no header row. The <strong>Chart editor</strong> panel opens on the right.</p><p><img src="'+n+'" alt="Bar chart placed to the right of its monthly data, with the Chart editor open on Setup"></p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Tap <strong>More formatting options</strong> (⋮) at the right end of the toolbar, then select <strong>Insert chart</strong>. See <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</p><h2 id="change-the-chart-type-and-data" tabindex="-1">Change the chart type and data <a class="header-anchor" href="#change-the-chart-type-and-data" aria-label="Permalink to &quot;Change the chart type and data&quot;">​</a></h2><ol><li><p>Open the <strong>Chart editor</strong>. If it&#39;s closed, click the chart&#39;s menu (⋮) in its title bar and select <strong>Edit chart</strong>.</p></li><li><p>On the <strong>Setup</strong> tab, set the options you need:</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Chart type</strong></td><td><strong>Bar chart</strong>, <strong>Line chart</strong>, <strong>Area chart</strong>, <strong>Pie chart</strong>, or <strong>Scatter chart</strong></td></tr><tr><td><strong>Data range</strong></td><td>The cells the chart plots. Type a range such as <code>A1:D20</code> and click <strong>Apply</strong>, or click <strong>Use selected range</strong></td></tr><tr><td><strong>X-axis</strong></td><td>The column used for category labels, or <strong>None</strong>. Called <strong>Label column</strong> for a pie chart</td></tr><tr><td><strong>Series</strong></td><td>The columns plotted as values. A pie chart has a single <strong>Value column</strong> instead</td></tr></tbody></table></li></ol><p>The chart redraws as you change each option.</p><h2 id="customize-the-title-legend-and-colors" tabindex="-1">Customize the title, legend, and colors <a class="header-anchor" href="#customize-the-title-legend-and-colors" aria-label="Permalink to &quot;Customize the title, legend, and colors&quot;">​</a></h2><ol><li>In the <strong>Chart editor</strong>, open the <strong>Customize</strong> tab.</li><li>Type a <strong>Chart title</strong>.</li><li>Choose a <strong>Legend</strong> position: <strong>Top</strong>, <strong>Bottom</strong>, <strong>Right</strong>, <strong>Left</strong>, or <strong>None</strong>.</li><li>Turn <strong>Show gridlines</strong> on or off. Pie charts have no gridlines, so the option is hidden for them.</li><li>Pick a <strong>Color palette</strong>: <strong>Theme (default)</strong>, <strong>Warm</strong>, or <strong>Cool</strong>.</li></ol><h2 id="move-resize-or-delete-a-chart" tabindex="-1">Move, resize, or delete a chart <a class="header-anchor" href="#move-resize-or-delete-a-chart" aria-label="Permalink to &quot;Move, resize, or delete a chart&quot;">​</a></h2><ol><li>Click the chart to select it.</li><li>Do one of the following: <ul><li>To move it, drag the chart. Press an arrow key to nudge it.</li><li>To resize it, drag an edge or a corner handle.</li><li>To delete it, press <code>Delete</code> or <code>Backspace</code>, or click the chart&#39;s menu (⋮) and select <strong>Delete chart</strong>.</li></ul></li></ol><h2 id="insert-an-image" tabindex="-1">Insert an image <a class="header-anchor" href="#insert-an-image" aria-label="Permalink to &quot;Insert an image&quot;">​</a></h2><ol><li>Click the cell where the image should start.</li><li>Click <strong>Insert image</strong> (the photo icon) in the toolbar and choose a file.</li></ol><p>The image appears at that cell. You can also paste an image, or drag an image file onto the grid to drop it where you release it.</p><p>To move an image, drag it. To resize it, drag a corner handle to keep its proportions, or an edge handle to stretch it. To delete it, select it and press <code>Delete</code>, or right-click it and select <strong>Delete image</strong>.</p><h3 id="on-a-phone-1" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone-1" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Tap <strong>More formatting options</strong> (⋮), then select <strong>Insert image</strong>.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>A chart whose range holds no numbers shows <code>Not enough numeric data in &lt;range&gt;</code>. Pick a range that includes a numeric column.</li><li>To replace an image, delete it and insert a new one.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/sheets/pivot-tables.html">Pivot tables</a> to summarize data before you chart it.</li><li><a href="/docs/sheets/conditional-formatting.html">Conditional formatting</a> to highlight values in the cells themselves.</li><li><a href="/docs/start/troubleshooting.html#select-at-least-2-rows-and-2-columns">Troubleshooting</a> if Wafflebase says <code>Select at least 2 rows and 2 columns.</code></li><li><a href="/docs/sheets/keyboard-shortcuts.html">Keyboard shortcuts</a> for nudging and deleting objects.</li></ul>',27)])])}const u=t(s,[["render",i]]);export{m as __pageData,u as default};
